insert into public.mant_registros
  (fecha, tipo, sector, emisor, maquina_texto, activo_id, trabajo, insumo, colaborador, fecha_fin, horas, origen) values
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Reparar guillotina. Se amuró un brazo tensor de carro. Se puso protección frente a las cuchillas y carteles de precaución.', null, 'Eric Chiarelli', '2022-10-18 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Soldar chapa en piso de reparaciones. Se tapó canaleta de salida con tapa de chapa.', null, 'Eric Chiarelli', '2022-10-18 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Reparar gancho de elevación y colocar abrazadera. Se reemplazaron dos morsetos rotos en la linga de acero y se ajustaron los otros dos.', null, 'Eric Chiarelli', '2022-10-18 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Hacer plato para máquina n°8. Se hizo plato nuevo, se reinstaló sensor y se volvió a brocar carro de alambre.', null, 'Eric Chiarelli', '2022-10-20 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Adaptar soporte para corte de tapas rurales. Se suplementó la base de la máquina para posicionar bien la altura del corte.', null, 'Eric Chiarelli', '2022-10-17 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-17 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Reparar antorcha de soldadora. El cable se pegó adentro. Se manipuló para que se despegue.', null, 'Eric Chiarelli', '2022-10-17 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-18 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Instalar máquina bobinadora nueva.', null, 'Eric Chiarelli', '2022-10-19 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Amurar máquina n°13. Se perforó el piso, se colocó maya y hormigón.', null, 'Eric Chiarelli', '2022-10-24 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Se purgó sistema de hidrolavadora.', null, 'Eric Chiarelli', '2022-10-20 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'RRHH', 'Ezequiel Hernandez', null, null, 'Colocar cartel de filosofía de la empresa', null, 'Eric Chiarelli', '2022-10-21 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'Montaje Rural', 'Omar Bender', null, null, 'Controlar horno. Cambiar resistencia cortada. Se cambiaron tres resistencias y un cable derretido en el piso. Se acomodó conmutador y termocupla de protección térmica.', null, 'Eric Chiarelli', '2022-10-21 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Fabricar llave para la máquina nueva.', null, 'Eric Chiarelli', '2022-10-20 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-20 00:00:00'::timestamptz, 'correctivo', 'RRHH', 'Ezequiel Hernandez', null, null, 'Instalar timbre. Poner en funcionamiento.', null, 'Eric Chiarelli', '2022-11-25 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-21 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Revisar boton de inicio de máquina n°14', null, 'Eric Chiarelli', '2022-10-21 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-21 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Reparar sensor de máquina n°8. Se realizó perforación nueva.', null, 'Eric Chiarelli', '2022-10-21 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-21 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Se extendió portarrollo de máquina N°8.', null, 'Eric Chiarelli', '2022-10-24 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-24 00:00:00'::timestamptz, 'correctivo', 'Lavado', 'Juan Rios', null, null, 'Revisar hidrolavadora. Se revisó y se probó pero falla. Quedó pendiente de reparación hasta la llegada del repuesto.', null, 'Eric Chiarelli', '2022-10-26 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-25 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Hacer portarollo para máqina n°15.', null, 'Eric Chiarelli', '2022-11-08 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-25 00:00:00'::timestamptz, 'correctivo', 'Montaje Rural', 'Omar Bender', null, null, 'Reparar ventilador. Bobina quemada, no sirve. Se cambió por ventilador nuevo.', null, 'Eric Chiarelli', '2022-11-01 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-25 00:00:00'::timestamptz, 'correctivo', 'Montaje Rural', 'Omar Bender', null, null, 'Soldar cable de linea cortado de soldador.', null, 'Eric Chiarelli', '2022-10-26 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-25 00:00:00'::timestamptz, 'correctivo', 'Montaje Rural', 'Omar Bender', null, null, 'Cambiar cable de resistencia por uno de alta temperatura. Se enfundaron los cables con espaguetti.', null, 'Eric Chiarelli', '2022-10-25 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-25 00:00:00'::timestamptz, 'correctivo', 'Montaje Rural', 'Omar Bender', null, null, 'Se armó tablero con toma trifásico para bomba y toma mónofásico para ventilador.', null, 'Eric Chiarelli', '2022-11-12 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-26 00:00:00'::timestamptz, 'correctivo', 'Bobinado', 'Oscar Rodriguez', null, null, 'Agregar chapón a guillotina. Se colocó chapón de contención de corte de prespan)', null, 'Eric Chiarelli', '2022-10-27 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-27 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Colocar rejilla para desague (marco y tapa)', null, 'Eric Chiarelli', '2022-10-28 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-27 00:00:00'::timestamptz, 'correctivo', 'Herrería', 'Juan Rios', null, null, 'Amurar morza.', null, 'Eric Chiarelli', '2022-10-28 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-27 00:00:00'::timestamptz, 'correctivo', 'RRHH', 'Ezequiel Hernandez', null, null, 'Colocar lámpara fluorescente en puesto de administración/recepción (Reubicado).', null, 'Eric Chiarelli', '2022-11-08 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
  ('2022-10-27 00:00:00'::timestamptz, 'correctivo', 'RRHH', 'Ezequiel Hernandez', null, null, 'Instalar reloj nuevo de fichada. Realizar colocación y cableado hasta el router de internet.', null, 'Eric Chiarelli', '2023-02-08 00:00:00'::timestamptz, null, 'RIT 7.1.3/28'),
